import 'package:flutter/material.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import '../../../../Core/Resources/app_fonts.dart';class BuildSocialLoginButton extends StatelessWidget {  final String? imagePath;  final String text;  final Color backgroundColor;  final Color textColor;  final VoidCallback onPressed;  const BuildSocialLoginButton({    super.key,     this.imagePath,    required this.text,    required this.backgroundColor,    this.textColor = Colors.white,    required this.onPressed,  });  @override  Widget build(BuildContext context) {    return Container(      width: 294.w,      height: 48.h,      decoration: BoxDecoration(        borderRadius: BorderRadius.circular(81).r,        color: backgroundColor,        border: backgroundColor == Colors.white ? Border.all(color: Color(0xffEFEFEF)) : null,      ),      child: MaterialButton(        onPressed: onPressed,        child: Row(          children: [            22.horizontalSpace,            imagePath == null ? SizedBox(              height: 24.h,              width: 24.w,            ) :            Image.asset(              imagePath!,              height: 24.h,              width: 24.w,            ),            37.horizontalSpace,            Text(              text,              style: AppTextStyles.h7Medium.copyWith(color: textColor),            ),          ],        ),      ),    );  }}